-- One attempt per reviewer per seed, including skips. Keep the earliest legacy attempt.
DELETE FROM reviews WHERE seed_case_id IS NOT NULL AND rowid NOT IN (
  SELECT MIN(rowid) FROM reviews WHERE seed_case_id IS NOT NULL GROUP BY player_id, seed_case_id
);
CREATE UNIQUE INDEX reviews_seed_once ON reviews(player_id, seed_case_id) WHERE seed_case_id IS NOT NULL;
-- Cover the rolling accuracy lookup.
CREATE INDEX reviews_seed_accuracy ON reviews(player_id, created_at DESC) WHERE seed_correct IS NOT NULL AND skipped = 0;
